  // Not to be used by end users
  NetOpImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  NetOpImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_NetOp,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_NetOp,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_NetOpPtr,
  );

  /// The record (store_write_cas) landed: the hex is handed out.
  OwnerStep? netPersisted() =>
      RustLib.instance.api.crateApiMemberNetOpNetPersisted(that: this);

  /// The record write failed (`error` = store_write_cas's text): no hex.
  OwnerStep? persistFailed({required String error}) => RustLib.instance.api
      .crateApiMemberNetOpPersistFailed(that: this, error: error);

  OwnerStep? signed({required List<int> der}) =>
      RustLib.instance.api.crateApiMemberNetOpSigned(that: this, der: der);
}

@sealed
class OwnerSessionImpl extends RustOpaque implements OwnerSession {
  // Not to be used by end users
  OwnerSessionImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  OwnerSessionImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_OwnerSession,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_OwnerSession,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_OwnerSessionPtr,
  );

  /// After an unclear make-network reply: "confirm network" (join2 §3.2) on the record this session made.
  OwnerStep checkNetwork() =>
      RustLib.instance.api.crateApiOwnerOwnerSessionCheckNetwork(that: this);

  /// The user's answer to a ConfirmCountry step.
  OwnerStep? countryConfirmed({required bool yes}) => RustLib.instance.api
      .crateApiOwnerOwnerSessionCountryConfirmed(that: this, yes: yes);

  String last4() =>
      RustLib.instance.api.crateApiOwnerOwnerSessionLast4(that: this);

  /// The net record was sealed and written (fsynced): network/join goes out (op/nonce first), or — after "applied" —
  /// the session is an owner session again.
  OwnerStep? netPersisted() =>
      RustLib.instance.api.crateApiOwnerOwnerSessionNetPersisted(that: this);

  /// The SHA-256 of this login's verified DAC (lowercase hex; "" = not verified): which own node this session is.
  String nodeDacHash() =>
      RustLib.instance.api.crateApiOwnerOwnerSessionNodeDacHash(that: this);

  OwnerStep? onFrame({required List<int> frame}) => RustLib.instance.api
      .crateApiOwnerOwnerSessionOnFrame(that: this, frame: frame);

  /// The last PersistNet failed (sealing or store_write_cas): stop; nothing more is sent (join2 §3.1). `error`: what
  /// failed — exactly store_write_cas's "changed elsewhere" line for a generation mismatch, else the reason.
  OwnerStep? persistFailed({required String error}) => RustLib.instance.api
      .crateApiOwnerOwnerSessionPersistFailed(that: this, error: error);

  /// "Confirm network" (join2 §3.2) for one of this phone's net records (opened by Kotlin; `record_gen` = the
  /// generation store_read_sealed gave): info key 10 / key 9 against the record; a match makes it applied.
  OwnerStep requestConfirmNetwork({
    required List<int> recordPlain,
    required BigInt recordGen,
  }) => RustLib.instance.api.crateApiOwnerOwnerSessionRequestConfirmNetwork(
    that: this,
    recordPlain: recordPlain,
    recordGen: recordGen,
  );

  /// remove-member §2.4: one info read whose body comes back as is (OwnerStep.info; empty = could not be read).
  OwnerStep requestInfo() =>
      RustLib.instance.api.crateApiOwnerOwnerSessionRequestInfo(that: this);

  /// Join this (claimed, verified at this login) node to the network of an opened net record (join2 §3.3).
  /// `record_gen`: the generation store_read_sealed gave (every record write of the join is a CAS from it).
  /// admin_pub / owner_enc_pub: this phone's keys (Kotlin publicKeys).
  /// `removed_confirmed`: the user answered yes to the ConfirmRemoved question (remove-member §2.0 rule 2).
  OwnerStep requestJoinNetwork({
    required List<int> recordPlain,
    required BigInt recordGen,
    required List<int> adminPub,
    required List<int> ownerEncPub,
    required bool removedConfirmed,
  }) => RustLib.instance.api.crateApiOwnerOwnerSessionRequestJoinNetwork(
    that: this,
    recordPlain: recordPlain,
    recordGen: recordGen,
    adminPub: adminPub,
    ownerEncPub: ownerEncPub,
    removedConfirmed: removedConfirmed,
  );

  /// member-join §4 step 4: a join request for a pasted invite (`invite_hex`), from this login's verified node.
  /// `pend_gen` / `pend_plain`: `mpend/<net_id>` as read (0 / None = none, or None = does not open: overwritten from
  /// `pend_gen`). `owner_enc_pub`: this phone's key (Kotlin publicKeys). Steps: SignOwner (sig_enc) -> SignOwner
  /// (join request) -> PersistPend -> Answer {hex, sas}; or straight the Answer when the pending one is reused.
  OwnerStep requestJoinreq({
    required String inviteHex,
    required String name,
    required BigInt pendGen,
    Uint8List? pendPlain,
    required List<int> ownerEncPub,
  }) => RustLib.instance.api.crateApiOwnerOwnerSessionRequestJoinreq(
    that: this,
    inviteHex: inviteHex,
    name: name,
    pendGen: pendGen,
    pendPlain: pendPlain,
    ownerEncPub: ownerEncPub,
  );

  /// 「離開網路」(254-app-leave v4.1 §3): the owner-op `network/leave` {}; a reply other than 0 (and a refused op/nonce or a
  /// failed signature) reads info and answers with `flow::leave_outcome`. Phone records are never written.
  OwnerStep requestLeaveNetwork() => RustLib.instance.api
      .crateApiOwnerOwnerSessionRequestLeaveNetwork(that: this);

  /// After an applied join: one `status` read, answered as connected / not yet / unknown (join2 §3.3-7).
  /// `secs_since_join`: seconds from the join reply to now.
  OwnerStep requestLinkCheck({required BigInt secsSinceJoin}) =>
      RustLib.instance.api.crateApiOwnerOwnerSessionRequestLinkCheck(
        that: this,
        secsSinceJoin: secsSinceJoin,
      );

  /// make-network on this (claimed, not joined) node — design §5.4. The first step is SignAdmin (net_config).
  /// owner_enc_pub / admin_pub: this phone's keys (Kotlin publicKeys). The node's dac_pub / ecdh_pub come from the
  /// node_cert verified at this login, never from the node's word alone.
  OwnerStep requestMakeNetwork({
    required String netName,
    required int channel,
    required List<int> ownerEncPub,
    required List<int> adminPub,
  }) => RustLib.instance.api.crateApiOwnerOwnerSessionRequestMakeNetwork(
    that: this,
    netName: netName,
    channel: channel,
    ownerEncPub: ownerEncPub,
    adminPub: adminPub,
  );

  /// member-join §4 step 8: this (own, verified) node joins the network of an imported mnet record (read at
  /// `mnet_gen`; every write is a CAS PersistMnet). Dev only.
  OwnerStep requestMemberJoin({
    required List<int> mnetPlain,
    required BigInt mnetGen,
  }) => RustLib.instance.api.crateApiOwnerOwnerSessionRequestMemberJoin(
    that: this,
    mnetPlain: mnetPlain,
    mnetGen: mnetGen,
  );

  /// 「把新密碼送給節點」(remove-member §3.2) to this (own, verified) node from an opened record: the admin's net
  /// record (`member` false; `admin_pub` signs the node's fresh secrets) or a member's mnet (`member` true). Never
  /// called on its own: only from the button (or right after a join whose node is behind, §3.5).
  OwnerStep requestSendUpdate({
    required List<int> recordPlain,
    required bool member,
    required List<int> adminPub,
  }) => RustLib.instance.api.crateApiOwnerOwnerSessionRequestSendUpdate(
    that: this,
    recordPlain: recordPlain,
    member: member,
    adminPub: adminPub,
  );

  /// `settings/set` {20: {1: ssid, 2: passphrase}} (an owner-op; §3.3): the phone AP. The passphrase stays in here
  /// and in the encrypted request; it is never part of a step's text.
  OwnerStep requestSetAp({required String ssid, required String passphrase}) =>
      RustLib.instance.api.crateApiOwnerOwnerSessionRequestSetAp(
        that: this,
        ssid: ssid,
        passphrase: passphrase,
      );

  /// `settings/set` {2: country} (an owner-op; 254-p3-impl §3.3): only while not in a network (else reason 14).
  /// The answer is the applied settings.
  OwnerStep requestSetCountry({required String country}) => RustLib.instance.api
      .crateApiOwnerOwnerSessionRequestSetCountry(that: this, country: country);

  /// `settings/get` {} — 254-p3-impl §3.3
  OwnerStep requestSettings() =>
      RustLib.instance.api.crateApiOwnerOwnerSessionRequestSettings(that: this);

  /// `ssh_keys/set` {1: [lines]} (an owner-op; P2): the node keeps every line it did not add for an app, so this adds
  /// (or replaces the app-added) keys. op/nonce goes out first; its answer becomes a Sign step.
  OwnerStep requestSshKeys({required List<String> lines}) => RustLib
      .instance
      .api
      .crateApiOwnerOwnerSessionRequestSshKeys(that: this, lines: lines);

  OwnerStep requestStatus() =>
      RustLib.instance.api.crateApiOwnerOwnerSessionRequestStatus(that: this);

  /// member-join §8: status, then info, then an Answer; `status_view` gives the page.
  OwnerStep requestStatusPage() => RustLib.instance.api
      .crateApiOwnerOwnerSessionRequestStatusPage(that: this);

  /// 254-app-update §11: send the update's pending request (the last Send action of `sw`) on this session; owner-ops
  /// go op/nonce -> Sign -> the request with key 31. The answer comes back as an Answer step with `sw` set (then
  /// `sw_answer`), or the session ends (Ended: the caller tells `sw.lost`).
  OwnerStep requestSw({required SwUpdate sw}) => RustLib.instance.api
      .crateApiOwnerOwnerSessionRequestSw(that: this, sw: sw);

  /// After a Wait step.
  OwnerStep? resumeUpdate() =>
      RustLib.instance.api.crateApiOwnerOwnerSessionResumeUpdate(that: this);

  OwnerStep? signed({required List<int> der}) => RustLib.instance.api
      .crateApiOwnerOwnerSessionSigned(that: this, der: der);

  /// The last status page read as the page shows it (status page v8.1 §2-§3). `has_net` / `has_mnet`: this phone holds
  /// a net/ (it made a network) / an mnet/ record — the claimed-node sentence names the matching join button.
  StatusView statusView({required bool hasNet, required bool hasMnet}) =>
      RustLib.instance.api.crateApiOwnerOwnerSessionStatusView(
        that: this,
        hasNet: hasNet,
        hasMnet: hasMnet,
      );

  /// The node's answer to `request_sw`, to the update; its next action.
  SwAction swAnswer({required SwUpdate sw, required BigInt nowMs}) => RustLib
      .instance
      .api
      .crateApiOwnerOwnerSessionSwAnswer(that: this, sw: sw, nowMs: nowMs);

  /// remove-member §3.5: the status page's line about this node's secrets, from the record of the network info key
  /// 10 names (`record_plain`: net/ when `member` false, mnet/ when true) and the last status-page read. "" = none;
  /// `button` = show 「把新密碼送給節點」.
  UpdateHint updateHint({
    required List<int> recordPlain,
    required bool member,
  }) => RustLib.instance.api.crateApiOwnerOwnerSessionUpdateHint(
    that: this,
    recordPlain: recordPlain,
    member: member,
  );
}

